Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "sender">Common</param>
/// <param name = "e">DataEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    DataEventHandler(tableStr(InventTransOrigin), DataEventType::Inserting)]
public static void InventTransOrigin_onInserting(Common sender, DataEventArgs e)
{
    InventTransOrigin   inventTransOrigin = sender as InventTransOrigin;

    if (inventTransOrigin.referenceCategory == InventTransType::Sales)
    {
        InventTransOrigin.AVACustVendReference = SalesTable::find(inventTransOrigin.ReferenceId).CustAccount;
    }
    if (inventTransOrigin.ReferenceCategory == InventTransType::Purch)
    {
        InventTransOrigin.AVACustVendReference = PurchTable::find(inventTransOrigin.ReferenceId).OrderAccount;
    }
}
